using System.Text.Json;
using Sia.Spirv.Compiler.Compilation;
using Sia.Spirv.Compiler.Translation;

var inputs = JsonSerializer.Deserialize<Input[]>(File.ReadAllText(args[0]))!;
string destination = Path.GetFullPath(args[1]); Directory.CreateDirectory(destination);
var target = SpirvCompilationTarget.Default with { Version = 0x00010300 };
var results = new List<object>();
foreach (var input in inputs) {
    try {
        byte[] binary = input.Path.EndsWith(".spv") ? File.ReadAllBytes(input.Path)
            : ShaderTranslator.WgslToSpirv(File.ReadAllText(input.Path), target);
        File.WriteAllBytes(Path.Combine(destination, input.Name + ".spv"), binary);
        string? error = null;
        try { File.WriteAllText(Path.Combine(destination, input.Name + ".wgsl"), ShaderTranslator.SpirvToWgsl(binary, target)); }
        catch (Exception ex) { error = ex.ToString(); }
        results.Add(new { input.Name, input.Path, Compiled = true, Roundtrip = error is null, Error = error });
    }
    catch (Exception ex) { results.Add(new { input.Name, input.Path, Compiled = false, Roundtrip = false, Error = ex.ToString() }); }
}
File.WriteAllText(Path.Combine(destination, "results.json"), JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine($"Processed {inputs.Length} inputs.");
record Input(string Name, string Path);

