"""A defined u32 grammar plus explicitly separate diagnostic/feature probes."""
from dataclasses import dataclass, replace
import random
import struct

MASK = 0xffffffff
FAMILIES = ('arithmetic', 'vector', 'aggregate', 'control', 'effects', 'pointer')
INPUTS = ((0, 1, MASK, 31), (MASK, 0x80000000, 7, 3), (7, 13, 0x7fffffff, 0), (32, 0x12345678, 0xabcdef01, 17))
HEADER = '''@group(0) @binding(0) var<storage, read> inputs: array<u32>;
@group(0) @binding(1) var<storage, read_write> outputs: array<u32>;
'''


@dataclass(frozen=True)
class Expr:
    op: str
    args: tuple

    def text(self):
        folded = self.folded()
        if folded != self: return folded.text()
        if self.op == 'const': return f'{self.args[0]}u'
        if self.op == 'var': return self.args[0]
        left, right = (a.text() for a in self.args)
        if self.op in ('/', '%'): right = f'({right} | 1u)'
        if self.op in ('<<', '>>'): right = f'({right} & 31u)'
        return f'({left} {self.op} {right})'

    def folded(self):
        # Positive runtime cases must not accidentally contain a constant-stage
        # overflowing shift. Constant-only trees become representable literals;
        # constant-expression diagnostic differences belong in separate probes.
        if self.op in ('const', 'var'): return self
        args = tuple(a.folded() for a in self.args)
        node = Expr(self.op, args)
        return Expr('const', (node.value({}),)) if all(a.op == 'const' for a in args) else node

    def value(self, env):
        if self.op == 'const': return self.args[0]
        if self.op == 'var': return env[self.args[0]]
        left, right = (a.value(env) for a in self.args)
        if self.op in ('/', '%'): right |= 1
        if self.op in ('<<', '>>'): right &= 31
        result = {'+': lambda: left + right, '-': lambda: left - right, '*': lambda: left * right,
                  '^': lambda: left ^ right, '&': lambda: left & right, '|': lambda: left | right,
                  '/': lambda: left // right, '%': lambda: left % right,
                  '<<': lambda: left << right, '>>': lambda: left >> right}[self.op]()
        return result & MASK

    def shrinks(self):
        if self != Expr('const', (0,)): yield Expr('const', (0,))
        if self.op in ('const', 'var'): return
        yield from self.args
        for index, argument in enumerate(self.args):
            for smaller in argument.shrinks():
                args = list(self.args); args[index] = smaller
                yield Expr(self.op, tuple(args))


def expression(rng, depth):
    if not depth or rng.randrange(4) == 0:
        return Expr('var', (rng.choice('xyz'),)) if rng.randrange(2) else Expr('const', (rng.choice((0, 1, 2, 31, 32, 0x80000000, MASK, rng.getrandbits(32))),))
    return Expr(rng.choice(('+', '-', '*', '^', '&', '|', '/', '%', '<<', '>>')),
                (expression(rng, depth - 1), expression(rng, depth - 1)))


@dataclass(frozen=True)
class Case:
    seed: int
    family: str
    exprs: tuple
    trips: int

    @classmethod
    def make(cls, seed, family):
        rng = random.Random(seed)
        return cls(seed, family, tuple(expression(rng, 3) for _ in range(4)), rng.randint(1, 8))

    def source(self, variant=0):
        ex = [e.text() for e in self.exprs]
        header = HEADER
        if variant: header += 'fn identity(value: u32) -> u32 { return value ^ 0u; }\n'
        if self.family == 'effects':
            header += '''var<private> state: u32;
fn step(value: u32) -> u32 { state = state + 1u; return value + state; }
fn nested(value: u32) -> u32 { let first = step(value); return first + step(value ^ 7u); }
'''
        if self.family == 'pointer':
            header += 'fn bump(p: ptr<function, u32>, value: u32) { *p = *p + value; }\n'
        start = 'var' if variant else 'let'
        body = f'{start} x = inputs[0]; {start} y = inputs[1]; {start} z = inputs[2];\n'
        if variant: body += 'let unused = (x ^ z) + 17u;\n'
        if self.family == 'arithmetic':
            results = ex
        elif self.family == 'vector':
            body += f'let v = vec4<u32>({", ".join(ex)}); let w = v.wzyx ^ vec4<u32>(y);\n'
            results = ['v[x & 3u]', 'w.x', 'v.z', 'w.w']
        elif self.family in ('aggregate', 'pointer'):
            body += f'var a = array<u32, 4>({", ".join(ex)}); let i = x & 3u; let old = a[i];\n'
            body += 'bump(&a[i], y);\n' if self.family == 'pointer' else 'a[i] = old + y;\n'
            results = ['old', 'a[i]', 'a[(i + 1u) & 3u]', 'a[3u]']
        elif self.family == 'control':
            body += f'''var a = x; var b = y; var total = z;
for (var i = 0u; i < {self.trips}u; i = i + 1u) {{
    let old = a; a = b; b = old;
    switch (i % 3u) {{
        case 0u: {{ total = total + a; }}
        case 1u: {{ continue; }}
        default: {{ total = total ^ b; }}
    }}
    total = total + i;
}}
'''
            results = ['a', 'b', 'total', 'select(x, y, x < y)']
        elif self.family == 'effects':
            body += 'let first = step(x); let second = nested(y);\n'
            results = ['first', 'second', 'state', ex[3]]
        else: raise ValueError(self.family)
        for index, result in enumerate(results):
            body += f'outputs[{index}u] = ' + (f'identity({result})' if variant else result) + ';\n'
        return header + '@compute @workgroup_size(1) fn main() {\n' + body + '}\n'

    def expected(self, inputs):
        x, y, z = inputs[:3]
        values = [e.value(dict(x=x, y=y, z=z)) for e in self.exprs]
        if self.family == 'arithmetic': return values
        if self.family == 'vector': return [values[x & 3], values[3] ^ y, values[2], values[0] ^ y]
        if self.family in ('aggregate', 'pointer'):
            index = x & 3; old = values[index]; values[index] = (old + y) & MASK
            return [old, values[index], values[(index + 1) & 3], values[3]]
        if self.family == 'effects': return [(x + 1) & MASK, ((y + 2) + ((y ^ 7) + 3)) & MASK, 3, values[3]]
        a, b, total = x, y, z
        for index in range(self.trips):
            a, b = b, a
            if index % 3 == 1: continue
            total = (total + a) & MASK if index % 3 == 0 else total ^ b
            total = (total + index) & MASK
        return [a, b, total, y if x < y else x]

    def shrinks(self):
        if self.trips > 1: yield replace(self, trips=1)
        for index, expression in enumerate(self.exprs):
            for smaller in expression.shrinks():
                exprs = list(self.exprs); exprs[index] = smaller
                yield replace(self, exprs=tuple(exprs))


def probes(seed):
    rng = random.Random(seed)
    index = rng.randint(4, 99)
    def compute(body): return HEADER + '@compute @workgroup_size(1) fn main() { ' + body + ' }\n'
    a, b = rng.randint(0, 10), rng.randint(0, 10)
    half_bits = int.from_bytes(struct.pack('<ee', a, b), 'little')
    # Probes have no execution oracle: some deliberately exercise undefined
    # runtime accesses or dialect-only constructs. Acceptance is not correctness.
    return [
        ('enable-subgroups', 'feature', 'enable subgroups;\n' + compute('_ = subgroupAdd(1u);')),
        ('runtime-oob', 'runtime-indeterminate', compute(f'let i = {index}; outputs[0] = vec4<u32>(1u)[i];')),
        ('constant-oob', 'must-reject', compute(f'outputs[0] = vec4<u32>(1u)[{index}];')),
        ('abstract-bitcast', 'constant-assert', f'const_assert bitcast<u32>({0xffffffff - a}) == {0xffffffff - a}u;\n' + compute('outputs[0] = 1u;')),
        ('f16-bitcast', 'constant-assert', f'enable f16;\nconst_assert bitcast<u32>(bitcast<vec2<f16>>(vec2({a}, {b}))) == {half_bits}u;\n' + compute('outputs[0] = 1u;')),
        ('private-uniform-copy', 'uniformity', '''var<private> copy: u32;
var<workgroup> data: array<u32, 128>;
@compute @workgroup_size(4) fn main(@builtin(workgroup_id) id: vec3<u32>) {
copy = id.x; _ = workgroupUniformLoad(&data[copy]); }
'''),
        ('const-clamp-bounds', 'must-reject', compute('outputs[0] = clamp(inputs[0], 2u, 1u);')),
        ('let-clamp-bounds', 'runtime-diagnostic', compute('let low = 2u; outputs[0] = clamp(inputs[0], low, 1u);')),
        ('texture-constant-offset', 'texture', '''@group(0) @binding(0) var t: texture_2d<f32>;
@group(0) @binding(1) var s: sampler;
@fragment fn main() -> @location(0) vec4<f32> {
return textureSample(t, s, vec2<f32>(0f), vec2<i32>(1, 2) + vec2<i32>(3, 4)); }
'''),
    ]

