"""Strict, single-invocation integer SPIR-V diagnostic interpreter, not a GPU model."""
from copy import deepcopy
from dataclasses import dataclass
import struct


class Unsupported(Exception):
    pass


class ExecutionFault(Exception):
    pass


@dataclass(frozen=True)
class Pointer:
    root: int
    indices: tuple = ()


def instructions(binary):
    if len(binary) < 20 or len(binary) % 4:
        raise ExecutionFault("malformed SPIR-V size")
    words = struct.unpack('<' + 'I' * (len(binary) // 4), binary)
    if words[0] != 0x07230203:
        raise ExecutionFault("invalid SPIR-V magic")
    offset = 5
    while offset < len(words):
        count, opcode = words[offset] >> 16, words[offset] & 65535
        if not count or offset + count > len(words):
            raise ExecutionFault("malformed instruction length")
        yield opcode, words[offset + 1:offset + count]
        offset += count


class Module:
    def __init__(self, binary):
        self.ops = list(instructions(binary))
        self.types, self.constants, self.globals, self.functions = {}, {}, [], {}
        self.decorations, self.entry = {}, None
        local_sizes = []
        function = None
        for op, a in self.ops:
            if op == 15:
                if self.entry is not None or a[0] != 5:
                    raise Unsupported("one compute entry point required")
                self.entry = a[1]
            elif op == 16 and a[1] == 17:
                local_sizes.append(a[2:])
            elif op == 71:
                self.decorations.setdefault(a[0], {})[a[1]] = a[2:]
            elif op in (19, 20, 21, 23, 28, 29, 30, 32, 33):
                self.types[a[0]] = (op, a[1:])
            elif op in (41, 42, 43, 44, 46):
                if op == 43:
                    typ = self.types[a[0]]
                    if typ[0] != 21 or typ[1][0] != 32:
                        raise Unsupported("only 32-bit integer constants")
                    value = a[2]
                elif op == 44:
                    value = [deepcopy(self.constants[v]) for v in a[2:]]
                elif op == 46:
                    value = self.zero(a[0])
                else:
                    value = op == 41
                self.constants[a[1]] = value
            elif op == 54:
                function = {'params': [], 'blocks': {}}
                self.functions[a[1]] = function
            elif op == 55:
                function['params'].append(a[1])
            elif op == 56:
                function = None
            elif op == 248:
                block = []
                function['blocks'][a[0]] = block
            elif function is not None:
                block.append((op, a))
            elif op == 59:
                self.globals.append(a)
        if local_sizes != [(1, 1, 1)]:
            raise Unsupported("only a literal 1x1x1 workgroup")

    def zero(self, type_id, runtime_length=4):
        op, a = self.types[type_id]
        if op == 20:
            return False
        if op == 21 and a[0] == 32:
            return 0
        if op == 23:
            return [self.zero(a[0], runtime_length) for _ in range(a[1])]
        if op == 28:
            return [self.zero(a[0], runtime_length) for _ in range(self.constants[a[1]])]
        if op == 29:
            return [self.zero(a[0], runtime_length) for _ in range(runtime_length)]
        if op == 30:
            return [self.zero(t, runtime_length) for t in a]
        raise Unsupported(f"zero initializer for type opcode {op}")

    def execute(self, inputs, budget=100000):
        memory, global_values, output_root = {}, {}, None
        for a in self.globals:
            type_id, var_id, _ = a[:3]
            pointee = self.types[type_id][1][1]
            binding = self.decorations.get(var_id, {}).get(33)
            if binding is not None:
                if self.decorations[var_id].get(34) != (0,) or binding[0] not in (0, 1):
                    raise Unsupported("only set 0 bindings 0/1")
                words = list(inputs) if binding[0] == 0 else [0xA5A5A5A5] * 4
                value = self.zero(pointee, len(words))
                # The generated ABI has one runtime array, possibly nested in
                # single-member SPIR-V buffer wrapper structures.
                node, typ = value, pointee
                while self.types[typ][0] == 30:
                    if len(self.types[typ][1]) != 1:
                        raise Unsupported("buffer wrapper must have one member")
                    node, typ = node[0], self.types[typ][1][0]
                if self.types[typ] != (29, (self._u32_type(),)):
                    raise Unsupported("runtime u32 buffer required")
                node[:] = words
                if binding[0] == 1:
                    output_root = var_id
            else:
                value = deepcopy(self.constants[a[3]]) if len(a) > 3 else None
            memory[var_id] = value
            global_values[var_id] = Pointer(var_id)
        steps = [budget]
        next_local = [max(memory, default=0) + 1]

        def read(pointer):
            value = memory[pointer.root]
            for index in pointer.indices:
                if not isinstance(value, list) or not 0 <= index < len(value):
                    raise ExecutionFault("out-of-bounds or nonaggregate memory access")
                value = value[index]
            def defined(v): return all(defined(x) for x in v) if isinstance(v, list) else v is not None
            if not defined(value):
                raise ExecutionFault("uninitialized memory read")
            return deepcopy(value)

        def write(pointer, value):
            if not pointer.indices:
                memory[pointer.root] = deepcopy(value)
                return
            parent = Pointer(pointer.root, pointer.indices[:-1])
            # Read without copying: stores must affect the original allocation.
            target = memory[parent.root]
            for index in parent.indices:
                if not isinstance(target, list) or not 0 <= index < len(target):
                    raise ExecutionFault("invalid store projection")
                target = target[index]
            index = pointer.indices[-1]
            if not isinstance(target, list) or not 0 <= index < len(target):
                raise ExecutionFault("out-of-bounds store")
            target[index] = deepcopy(value)

        def lanes(fn, *values):
            arrays = [v for v in values if isinstance(v, list)]
            if arrays:
                count = len(arrays[0])
                if any(len(v) != count for v in arrays):
                    raise ExecutionFault("vector shape mismatch")
                return [lanes(fn, *(v[i] if isinstance(v, list) else v for v in values)) for i in range(count)]
            return fn(*values)

        def signed(value):
            return value - 0x100000000 if value & 0x80000000 else value

        def binary(op, x, y):
            if op in (134, 137) and not y:
                raise ExecutionFault("zero divisor")
            if op in (194, 195, 196) and y >= 32:
                raise ExecutionFault("undefined SPIR-V shift")
            functions = {
                128: lambda: (x + y) & 0xffffffff, 130: lambda: (x - y) & 0xffffffff,
                132: lambda: (x * y) & 0xffffffff, 134: lambda: x // y, 137: lambda: x % y,
                164: lambda: x == y, 165: lambda: x != y, 166: lambda: bool(x or y), 167: lambda: bool(x and y),
                170: lambda: x == y, 171: lambda: x != y, 172: lambda: x > y, 173: lambda: signed(x) > signed(y),
                174: lambda: x >= y, 175: lambda: signed(x) >= signed(y), 176: lambda: x < y,
                177: lambda: signed(x) < signed(y), 178: lambda: x <= y, 179: lambda: signed(x) <= signed(y),
                194: lambda: x >> y, 195: lambda: (signed(x) >> y) & 0xffffffff,
                196: lambda: (x << y) & 0xffffffff, 197: lambda: x | y, 198: lambda: x ^ y, 199: lambda: x & y,
            }
            return functions[op]()

        def call(function_id, arguments, depth=0):
            if depth > 32:
                raise ExecutionFault("call depth exceeded")
            function = self.functions[function_id]
            values = dict(self.constants)
            values.update(global_values)
            values.update(zip(function['params'], arguments, strict=True))
            block_id, predecessor = next(iter(function['blocks'])), None
            owned = []
            while True:
                block = function['blocks'][block_id]
                # All phi inputs refer to predecessor state, never earlier phi writes.
                phis = {}
                for op, a in block:
                    if op == 245:
                        incoming = [(a[i], a[i + 1]) for i in range(2, len(a), 2)]
                        chosen = next((v for v, label in incoming if label == predecessor), None)
                        if chosen is None:
                            raise ExecutionFault("missing phi predecessor")
                        phis[a[1]] = deepcopy(values[chosen])
                values.update(phis)
                destination = None
                for op, a in block:
                    steps[0] -= 1
                    if steps[0] < 0:
                        raise ExecutionFault("instruction budget exceeded")
                    if op in (0, 8, 245, 246, 247, 317):
                        continue
                    if op == 59:
                        root_id = next_local[0]
                        next_local[0] += 1
                        owned.append(root_id)
                        memory[root_id] = deepcopy(values[a[3]]) if len(a) > 3 else None
                        # Allocation-only aggregates still have addressable leaves;
                        # reads remain undefined until those leaves are initialized.
                        if memory[root_id] is None:
                            def undefined(typ):
                                zero = self.zero(typ)
                                def clear(v): return [clear(x) for x in v] if isinstance(v, list) else None
                                return clear(zero)
                            memory[root_id] = undefined(self.types[a[0]][1][1])
                        values[a[1]] = Pointer(root_id)
                    elif op in (65, 66):
                        base = values[a[2]]
                        values[a[1]] = Pointer(base.root, base.indices + tuple(values[i] for i in a[3:]))
                    elif op == 61:
                        values[a[1]] = read(values[a[2]])
                    elif op == 62:
                        write(values[a[0]], values[a[1]])
                    elif op == 57:
                        values[a[1]] = call(a[2], [values[v] for v in a[3:]], depth + 1)
                    elif op in (80, 44):
                        values[a[1]] = [deepcopy(values[v]) for v in a[2:]]
                        if self.types[a[0]][0] == 23:
                            values[a[1]] = [lane for value in values[a[1]] for lane in (value if isinstance(value, list) else [value])]
                    elif op in (81, 77):
                        value = deepcopy(values[a[2]])
                        indices = a[3:] if op == 81 else [values[a[3]]]
                        for index in indices:
                            if not 0 <= index < len(value):
                                raise ExecutionFault("out-of-bounds composite extract")
                            value = value[index]
                        values[a[1]] = value
                    elif op in (82, 78):
                        value = deepcopy(values[a[3] if op == 82 else a[2]]); target = value
                        indices = a[4:] if op == 82 else [values[a[4]]]
                        for index in indices[:-1]: target = target[index]
                        if not 0 <= indices[-1] < len(target): raise ExecutionFault("invalid composite insert")
                        target[indices[-1]] = deepcopy(values[a[2] if op == 82 else a[3]])
                        values[a[1]] = value
                    elif op == 79:
                        combined = values[a[2]] + values[a[3]]
                        if any(i >= len(combined) for i in a[4:]): raise Unsupported("undefined shuffle lane")
                        values[a[1]] = [combined[i] for i in a[4:]]
                    elif op in (83, 113, 114, 124):
                        if op != 83 and self.types[a[0]][0] not in (21, 23): raise Unsupported("noninteger conversion")
                        values[a[1]] = deepcopy(values[a[2]])
                    elif op in (126, 168, 200):
                        fn = {126: lambda x: (-x) & 0xffffffff, 168: lambda x: not x, 200: lambda x: (~x) & 0xffffffff}[op]
                        values[a[1]] = lanes(fn, values[a[2]])
                    elif op == 169:
                        values[a[1]] = lanes(lambda c, x, y: x if c else y, values[a[2]], values[a[3]], values[a[4]])
                    elif op in (154, 155):
                        values[a[1]] = (any if op == 154 else all)(values[a[2]])
                    elif op in (128, 130, 132, 134, 137, 164, 165, 166, 167, 170, 171, 172, 173, 174, 175, 176, 177, 178, 179, 194, 195, 196, 197, 198, 199):
                        values[a[1]] = lanes(lambda x, y: binary(op, x, y), values[a[2]], values[a[3]])
                    elif op == 249:
                        destination = a[0]; break
                    elif op == 250:
                        destination = a[1] if values[a[0]] else a[2]; break
                    elif op == 251:
                        destination = dict(zip(a[2::2], a[3::2])).get(values[a[0]], a[1]); break
                    elif op in (253, 254):
                        result = deepcopy(values[a[0]]) if op == 254 else None
                        for root_id in owned: del memory[root_id]
                        return result
                    else:
                        raise Unsupported(f"executed opcode {op}")
                if destination is None:
                    raise ExecutionFault("block did not terminate")
                predecessor, block_id = block_id, destination

        if self.entry is None or output_root is None:
            raise Unsupported("missing compute entry/output binding")
        call(self.entry, [])
        output = memory[output_root]
        while isinstance(output, list) and len(output) == 1 and isinstance(output[0], list): output = output[0]
        return output

    def _u32_type(self):
        return next(t for t, desc in self.types.items() if desc == (21, (32, 0)))


def metrics(binary):
    ops = list(instructions(binary))
    return {'bytes': len(binary), 'instructions_without_debug': sum(op not in (2, 3, 4, 5, 6, 7, 8, 317, 330) for op, _ in ops),
            'loads': sum(op == 61 for op, _ in ops), 'stores': sum(op == 62 for op, _ in ops),
            'calls': sum(op == 57 for op, _ in ops), 'phis': sum(op == 245 for op, _ in ops),
            'function_variables': sum(op == 59 and a[2] == 7 for op, a in ops)}

