"""Bounded native Tint/Naga differential diagnostics. Python standard library only."""
import argparse
from collections import Counter
from dataclasses import asdict
import hashlib
import json
import platform
from pathlib import Path
import subprocess
import sys
import tempfile
import time

from generate import Case, Expr, FAMILIES, INPUTS, probes
from spirv_oracle import Module, Unsupported, ExecutionFault, metrics


def fingerprint(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def check_semantics(binary, case):
    """Unsupported execution is a coverage gap, never a successful oracle check."""
    try:
        module = Module(binary)
        for inputs in INPUTS:
            expected = case.expected(inputs)
            actual = module.execute(inputs)
            if actual != expected:
                return {'kind': 'semantic_mismatch', 'inputs': inputs, 'expected': expected, 'actual': actual}
        return {'kind': 'semantic_pass', 'input_vectors': len(INPUTS)}
    except Unsupported as error:
        return {'kind': 'oracle_unsupported', 'detail': str(error)}
    except ExecutionFault as error:
        return {'kind': 'execution_fault', 'detail': str(error)}


def command(arguments, timeout):
    started = time.monotonic()
    try:
        result = subprocess.run([str(a) for a in arguments], capture_output=True, timeout=timeout)
        return {'exit': result.returncode, 'seconds': time.monotonic() - started,
                'stdout': result.stdout[:8192].decode('utf-8', errors='replace'),
                'stderr': result.stderr[:8192].decode('utf-8', errors='replace')}
    except subprocess.TimeoutExpired:
        # subprocess.run kills and reaps the direct native CLI before returning.
        return {'exit': None, 'seconds': time.monotonic() - started, 'stderr': 'timeout', 'stdout': ''}


class Runner:
    def __init__(self, args):
        self.tools = {name: Path(getattr(args, name)).resolve(strict=True) for name in ('tint', 'naga', 'validator')}
        self.timeout = args.timeout
        self.commands = 0

    def invoke(self, arguments):
        self.commands += 1
        return dict(command(arguments, self.timeout), command=[str(a) for a in arguments])

    def compile(self, tool, source, destination):
        if tool == 'tint':
            args = [self.tools[tool], source, '--format', 'spirv', '--spirv-version', '1.3', '--disable-robustness', '-o', destination]
        else:
            args = [self.tools[tool], '--spirv-version', '1.3', '--index-bounds-check-policy', 'Unchecked',
                    '--buffer-bounds-check-policy', 'Unchecked', source, destination]
        return self.invoke(args)

    def read(self, tool, source, destination):
        args = [self.tools[tool], source, '--format', 'wgsl', '-o', destination] if tool == 'tint' else [self.tools[tool], source, destination]
        return self.invoke(args)

    def binary(self, tool, source, destination, route, case):
        result = self.compile(tool, source, destination)
        record = {'route': route, 'compile': result}
        if result['exit'] != 0:
            record['kind'] = failure_kind(result)
            return record
        if not destination.exists():
            return dict(record, kind='missing_binary')
        binary = destination.read_bytes()
        validation = self.invoke([self.tools['validator'], '--target-env', 'vulkan1.1', destination])
        record['validation'] = validation
        if validation['exit'] != 0:
            return dict(record, kind='validation_timeout' if validation['exit'] is None else 'invalid_spirv')
        record['metrics'] = metrics(binary)
        record.update(check_semantics(binary, case) if case else {'kind': 'probe_valid_binary'})
        return record

    def source(self, text, directory, case=None, roundtrip=False):
        directory.mkdir(parents=True, exist_ok=False)
        source = directory / 'source.wgsl'; source.write_text(text, encoding='utf-8')
        records = []
        for writer in ('tint', 'naga'):
            binary = directory / f'{writer}.spv'
            record = self.binary(writer, source, binary, writer, case)
            records.append(record)
            if not roundtrip or record['compile']['exit'] != 0 or record.get('validation', {}).get('exit') != 0:
                continue
            for reader in ('tint', 'naga'):
                wgsl = directory / f'{writer}-{reader}.wgsl'
                result = self.read(reader, binary, wgsl)
                route = f'{writer}>{reader}'
                if result['exit'] != 0 or not wgsl.exists():
                    records.append({'route': route, 'kind': 'reader_' + failure_kind(result), 'read': result})
                    continue
                for rewriter in ('tint', 'naga'):
                    output = directory / f'{writer}-{reader}-{rewriter}.spv'
                    records.append(self.binary(rewriter, wgsl, output, route + '>' + rewriter, case))
        base = [r for r in records if '>' not in r['route']]
        accepts = [r['compile']['exit'] == 0 for r in base]
        if accepts[0] != accepts[1]:
            records.append({'kind': 'acceptance_difference', 'route': 'tint|naga', 'accepted': dict(zip(('tint', 'naga'), accepts))})
        return records


def failure_kind(result):
    if result['exit'] is None: return 'compiler_timeout'
    if result['exit'] == 0: return 'missing_output'
    if result['exit'] < 0 or result['exit'] >= 0x80000000 or result['exit'] == 101 or 'panicked at' in result.get('stderr', '') or 'internal compiler error' in result.get('stderr', '').lower():
        return 'compiler_crash'
    return 'compiler_reject'


def decode_case(data):
    nodes = [0]
    def expr(value, depth=0):
        nodes[0] += 1
        if depth > 8 or nodes[0] > 256: raise ValueError('replay expression budget exceeded')
        op, args = value['op'], value['args']
        if op == 'const' and len(args) == 1 and type(args[0]) is int and 0 <= args[0] <= 0xffffffff:
            return Expr(op, (args[0],))
        if op == 'var' and len(args) == 1 and args[0] in ('x', 'y', 'z'):
            return Expr(op, (args[0],))
        if op in ('+', '-', '*', '^', '&', '|', '/', '%', '<<', '>>') and len(args) == 2:
            return Expr(op, tuple(expr(a, depth + 1) for a in args))
        raise ValueError('invalid typed replay expression')
    if data['family'] not in FAMILIES or type(data['trips']) is not int or not 1 <= data['trips'] <= 8 or len(data['exprs']) != 4:
        raise ValueError('invalid bounded replay case')
    return Case(data['seed'], data['family'], tuple(expr(e) for e in data['exprs']), data['trips'])


def reduce_case(runner, original, signature, variant, parent, limit):
    best, attempts, reductions = original, 0, 0
    target_roundtrip = '>' in signature[1]
    while attempts < limit:
        changed = False
        for candidate in best.shrinks():
            if attempts >= limit: break
            if len(candidate.source(variant)) >= len(best.source(variant)): continue
            attempts += 1
            with tempfile.TemporaryDirectory(prefix='reduce-', dir=parent) as scratch:
                rows = runner.source(candidate.source(variant), Path(scratch) / 'case', candidate, target_roundtrip)
            if any((r['kind'], r['route']) == signature for r in rows):
                best, changed = candidate, True
                reductions += 1
                break
        if not changed: break
    return best, {'attempts': attempts, 'reductions': reductions}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for tool in ('tint', 'naga', 'validator'): parser.add_argument('--' + tool, required=True)
    parser.add_argument('--output', type=Path, required=True, help='new output directory; never overwrites a run')
    parser.add_argument('--seed', type=lambda n: int(n, 0), default=0x5eed)
    parser.add_argument('--cases', type=int, default=48)
    parser.add_argument('--family', choices=FAMILIES)
    parser.add_argument('--probe-seeds', type=int, default=2)
    parser.add_argument('--roundtrip-cases', type=int, default=6)
    parser.add_argument('--timeout', type=float, default=10)
    parser.add_argument('--shrink-limit', type=int, default=24)
    parser.add_argument('--replay-case', type=Path)
    parser.add_argument('--fail-on', choices=('semantic', 'critical', 'none'), default='semantic',
                        help='semantic also fails on unsupported oracle coverage; critical additionally fails on crashes/timeouts')
    args = parser.parse_args()
    if not (0 <= args.cases <= 10000 and 0 <= args.probe_seeds <= 1000 and 0 <= args.roundtrip_cases <= args.cases
            and 0 < args.timeout <= 60 and 0 <= args.shrink_limit <= 200): parser.error('campaign bounds exceeded')
    runner = Runner(args)
    args.output.mkdir(parents=True, exist_ok=False)
    out = args.output.resolve()
    metadata = {'schema': 1, 'seed': args.seed, 'arguments': {k: str(v) if isinstance(v, Path) else v for k, v in vars(args).items()},
                'python': sys.version, 'platform': platform.platform(),
                'script_sha256': {name: fingerprint(Path(__file__).with_name(name)) for name in ('run.py', 'generate.py', 'spirv_oracle.py')},
                'tools': {k: {'path': str(v), 'sha256': fingerprint(v)} for k, v in runner.tools.items()},
                'profile': 'SPIR-V1.3, Vulkan1.1; unchecked indices; defined u32 cases; one invocation; no barriers/floats',
                'inputs': INPUTS}
    (out / 'metadata.json').write_text(json.dumps(metadata, indent=2), encoding='utf-8')
    records, reduced = [], set()
    # A broken executable/option/environment must fail preflight rather than
    # becoming thousands of spurious compiler differences.
    preflight = runner.source(Case.make(0, 'arithmetic').source(), out / 'preflight', Case.make(0, 'arithmetic'))
    if any(r['kind'] != 'semantic_pass' for r in preflight):
        (out / 'preflight.json').write_text(json.dumps(preflight, indent=2), encoding='utf-8')
        raise RuntimeError('preflight failed; inspect preflight.json before fuzzing')
    semantic_cases = [decode_case(json.loads(args.replay_case.read_text()))] if args.replay_case else [Case.make(args.seed + i, args.family or FAMILIES[i % len(FAMILIES)]) for i in range(args.cases)]
    for index, case in enumerate(semantic_cases):
        identifier = f'{index:04}-{case.family}-{case.seed}'
        (out / (identifier + '.case.json')).write_text(json.dumps(asdict(case), indent=2), encoding='utf-8')
        for variant in (0, 1):
            rows = runner.source(case.source(variant), out / f'{identifier}-v{variant}', case, index < args.roundtrip_cases)
            for row in rows: row.update(case=identifier, variant=variant, family=case.family, profile='defined-u32')
            records.extend(rows)
            for row in rows:
                signature = (row['kind'], row['route'])
                reducible = row['kind'] in ('semantic_mismatch', 'execution_fault', 'compiler_crash', 'invalid_spirv') or row['kind'] == 'compiler_reject' and '>' in row['route']
                if not reducible or signature in reduced or not args.shrink_limit:
                    continue
                reduced.add(signature)
                minimal, reduction = reduce_case(runner, case, signature, variant, out, args.shrink_limit)
                # Reproduce three times. A flaky result stays a candidate.
                confirmations = []
                confirmation_records = []
                for repeat in range(3):
                    repeated = runner.source(minimal.source(variant), out / f'{identifier}-min-{variant}-{len(reduced)}-{repeat}', minimal, '>' in row['route'])
                    confirmations.append(any((r['kind'], r['route']) == signature for r in repeated))
                    confirmation_records.append([r for r in repeated if (r['kind'], r['route']) == signature])
                prefix = out / f'finding-{len(reduced):03}'
                prefix.with_suffix('.wgsl').write_text(minimal.source(variant), encoding='utf-8')
                prefix.with_suffix('.case.json').write_text(json.dumps(asdict(minimal), indent=2), encoding='utf-8')
                prefix.with_suffix('.json').write_text(json.dumps({'signature': signature, 'original': identifier, 'variant': variant,
                    'reduction': reduction, 'confirmations': confirmations, 'confirmation_records': confirmation_records, 'record': row}, indent=2), encoding='utf-8')
        (out / 'results.json').write_text(json.dumps(records, indent=2), encoding='utf-8')
        if (index + 1) % 6 == 0: print(f'{index + 1}/{len(semantic_cases)} semantic cases', flush=True)
    for probe_seed in range(args.probe_seeds):
        for name, profile, source in probes(args.seed + probe_seed):
            identifier = f'probe-{probe_seed:03}-{name}'
            rows = runner.source(source, out / identifier)
            for row in rows: row.update(case=identifier, profile=profile)
            records.extend(rows)
    summary = {'semantic_cases': len(semantic_cases), 'probe_cases': args.probe_seeds * len(probes(0)),
               'native_commands': runner.commands, 'results': dict(Counter(r['kind'] for r in records)),
               'defined_results': dict(Counter(r['kind'] for r in records if r['profile'] == 'defined-u32')),
               'semantic_input_executions': sum(r.get('input_vectors', 0) for r in records),
               'reduced_signatures': len(reduced)}
    (out / 'results.json').write_text(json.dumps(records, indent=2), encoding='utf-8')
    (out / 'summary.json').write_text(json.dumps(summary, indent=2), encoding='utf-8')
    print(json.dumps(summary, indent=2))
    failure_kinds = {'semantic_mismatch', 'execution_fault', 'oracle_unsupported', 'invalid_spirv'}
    if args.fail_on == 'critical': failure_kinds.update(('compiler_crash', 'compiler_timeout', 'validation_timeout'))
    return 2 if args.fail_on != 'none' and any(r['kind'] in failure_kinds and r['profile'] == 'defined-u32' for r in records) else 0


if __name__ == '__main__':
    raise SystemExit(main())
